using UnityEngine; using UnityEngine.InputSystem; using NWD.Core;
namespace NWD.Player {
 [RequireComponent(typeof(CharacterController))] public sealed class CharacterMotor:MonoBehaviour,ICharacterMotor { public float walkSpeed=4,sprintSpeed=7,crouchSpeed=2,jumpHeight=1.2f,gravity=-20; CharacterController cc;float y;void Awake()=>cc=GetComponent<CharacterController>(); public void Move(Vector2 m,bool sprint,bool crouch,bool jump){if(cc.isGrounded){y=-2;if(jump)y=Mathf.Sqrt(jumpHeight*-2*gravity);}y+=gravity*Time.deltaTime;var speed=crouch?crouchSpeed:sprint?sprintSpeed:walkSpeed;cc.Move((transform.right*m.x+transform.forward*m.y)*speed*Time.deltaTime+Vector3.up*y*Time.deltaTime);} }
 public sealed class FirstPersonLook:MonoBehaviour { public Transform body;public float sensitivity=.1f;float pitch;public void Look(Vector2 delta){body.Rotate(Vector3.up*delta.x*sensitivity);pitch=Mathf.Clamp(pitch-delta.y*sensitivity,-85,85);transform.localRotation=Quaternion.Euler(pitch,0,0);} }
 public sealed class PlayerInputReader:MonoBehaviour,IPlayerInput { public InputActionReference move,look,sprint,crouch,jump,interact,aim,fire,reload,melee,nextWeapon,pause; public Vector2 Move=>move.action.ReadValue<Vector2>();public Vector2 Look=>look.action.ReadValue<Vector2>();public bool Sprint=>sprint.action.IsPressed();public bool Crouch=>crouch.action.IsPressed(); }
 public sealed class PlayerAvatar:MonoBehaviour { public CharacterMotor motor;public FirstPersonLook cameraLook;public PlayerInputReader input;void Update(){motor.Move(input.Move,input.Sprint,input.Crouch,input.jump.action.WasPressedThisFrame());cameraLook.Look(input.Look);} }
}
